    { const char * tb_v1042 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1042; }
    { const char * tb_v1043 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1043; }
    { const char * tb_v1044 = "// вырасти кусок: временный текущей области растёт там же, обычный — через realloc.\n"; *(const char * *)tb_grow(v_lines) = tb_v1044; }
    { const char * tb_v1045 = "// Кусок из внешней области (список создан снаружи, растёт внутри temp или шага цикла)\n"; *(const char * *)tb_grow(v_lines) = tb_v1045; }
    { const char * tb_v1046 = "// переезжает в обычную память: внутренняя область скоро отдаётся, а список живёт дольше.\n"; *(const char * *)tb_grow(v_lines) = tb_v1046; }
    { const char * tb_v1047 = "static void *tb_resize(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1047; }
    { const char * tb_v1048 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v1048; }
