    { const char * tb_v1693 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v1693; }
    { const char * tb_v1694 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v1694; }
